package dev.codex.lastzhelper;
import java.io.*;import java.nio.channels.*;import org.json.*;
/** Bounded phone validation. Every automation controller here is dry-run only. */
public final class PhoneCheck {
 public static void main(String[] args){try(DeviceInput.Scope inputs=new DeviceInput.Scope()){
  if(args.length<2)throw new IOException("Expected directory and inspect/world/roundtrip/trucks/bounty/chat mode");
  File dir=new File(args[0]),lockDir=new File("/data/local/tmp/codex-lastz-helper");lockDir.mkdirs();
  try(RandomAccessFile f=new RandomAccessFile(new File(lockDir,"control.lock"),"rw");FileChannel ch=f.getChannel();FileLock lock=ch.tryLock()){
   if(lock==null)throw new IOException("Controller already active");ControllerOwnership.check();RecoveryGuard.noInjector();
   try(DisplaySession display=new DisplaySession()){
    AutomationController c=new AutomationController(dir,new File(dir,"injector"),new File(dir,"input-agent.js"),new File(dir,"stop-request"),true,0);
    c.mode="phone-check";c.input.foreground();if(args.length>2&&"--screenshot".equals(args[args.length-1]))c.input.screenshot("before.png");
    if(args[1].equals("battle-return")){if(!TruckPolicy.MAIN_UID.equals(StateProbe.pinnedUid)||!(c.open("UIParkourBattleWin")||c.open("UIParkourBattleLose")))throw new IOException("Active Gaarix battle result required");c.returnFromBattle();System.out.println("Returned from battle result to Trucks; no new attack");}
    else if(args[1].equals("inspect"))System.out.println(c.input.action(new JSONObject().put("action","inspect")));
    else if(args[1].equals("map-region")){c.worldReady();System.out.println(c.input.action(new JSONObject().put("action","map-region")));}
    else if(args[1].equals("map-move")){c.worldReady();c.moveMap("west");System.out.println("Live clear-viewport map movement verified");}
    else if(args[1].equals("state-unavailable-check")){if(c.go(40,500,500))throw new IOException("State40 unexpectedly available");if(c.open("UISearchMonster"))throw new IOException("Unavailable-state search did not close");System.out.println("Unavailable state40 recognized from live text; skipped without sharing or attacking");}
    else if(args[1].equals("state-error-probe")){if(!c.open("UISearchMonster"))throw new IOException("Open existing coordinate search required");c.input.tapControl("UIManagerInstance/windows/UISearchMonster/View/gotoWorld/btn",0);for(int i=0;i<4;i++){System.out.println(c.input.action(new JSONObject().put("action","state-errors").put("inspectText",true)));c.input.pause(150);}}
    else if(args[1].equals("vip-read-controls")){if(!c.open("UIVip"))throw new IOException("VIP panel required");for(String name:new String[]{"get_btn","free_btn","get_btn_txt","free_btn_text","cur_day_des_text","box_btn_text","freeOpened","freeUnOpened","boxOpened","boxUnOpened","box_btn","free_text","free_des_text"})System.out.println(c.input.action(new JSONObject().put("action","ui-bounds").put("path","UIManagerInstance/windows/UIVip/View/"+name).put("stateOnly",true)));}
    else if(args[1].equals("boomer-read"))System.out.println(new BoomerReader(new MaintenanceContext(c)).read());
    else if(args[1].equals("event-carousel")){
     String card;try(GameMemory m=new GameMemory(c.cache)){if(m.state.getInt("modalWindowCount")!=1||!m.open("UIActivityCenterTable"))throw new IOException("Event Center alone required");card=BoomerEventTarget.find(m);}
     System.out.println(c.input.action(new JSONObject().put("action","ui-swipe").put("path",BoomerNavigationPolicy.EVENT+"tabScrollViewN").put("child","Viewport").put("direction","left").put("eventCarousel",true).put("eventCardPath",card)));c.input.pause(700);
    }
    else if(args[1].equals("ui-state"))System.out.println(c.input.action(new JSONObject().put("action","ui-bounds").put("path",args[2]).put("stateOnly",true)));
    else if(args[1].equals("chest-preview"))System.out.println(c.input.action(new JSONObject().put("action","chest-preview")));
    else if(args[1].equals("chest-reference-names"))System.out.println(c.input.action(new JSONObject().put("action","chest-reference-names")));
    else if(args[1].equals("xlua-scene-metadata"))System.out.println(c.input.action(new JSONObject().put("action","xlua-scene-metadata")));
    else if(args[1].equals("xlua-metadata"))System.out.println(c.input.action(new JSONObject().put("action","xlua-metadata")));
    else if(args[1].equals("ui-texts"))System.out.println(c.input.action(new JSONObject().put("action","state-errors").put("inspectText",true)));
    else if(args[1].equals("ui-metadata"))System.out.println(c.input.action(new JSONObject().put("action","ui-metadata")));
    else if(args[1].equals("mail-coverage-tabs")){if(!c.open("UIMailNew4"))throw new IOException("Already-open Mail required");System.out.println(new JSONObject().put("event","mail-header-before").put("snapshot",MailHeaderStateProbe.read(c.cache)));for(int index=1;index<=6;index++){try(GameMemory m=new GameMemory(c.cache)){if(!MailCoverageReader.knownWindows(m))throw new IOException("Unknown overlay over Mail");}c.input.action(new JSONObject().put("action","ui-tap").put("path",MailPolicy.VIEW+"_toggles/#"+index).put("mailInspectionIndex",index));long waitUntil=System.currentTimeMillis()+3000;JSONObject snapshot;do{c.input.pause(150);snapshot=MailCoverageReader.read(c.cache,StateProbe.pinnedUid);if(snapshot.optBoolean("contextConfirmed")&&snapshot.optInt("groupType",-1)==MailPolicy.type(index)&&snapshot.optBoolean("observedFieldsStableAcrossReads"))break;}while(System.currentTimeMillis()<waitUntil);if(!snapshot.optBoolean("contextConfirmed")||snapshot.optInt("groupType",-1)!=MailPolicy.type(index)||snapshot.optString("coverageState").equals("BLOCKED")||!snapshot.optBoolean("observedFieldsStableAcrossReads"))throw new IOException("Requested Mail tab not confirmed or unstable; stopped");System.out.println(new JSONObject().put("event","mail-tab-coverage").put("requestedIndex",index).put("snapshot",snapshot));}System.out.println(new JSONObject().put("event","mail-header-after").put("snapshot",MailHeaderStateProbe.read(c.cache)));c.input.action(new JSONObject().put("action","ui-tap").put("path",MailPolicy.VIEW+"_btnClose").put("mailInspectionIndex",0));c.input.pause(350);if(c.open("UIMailNew4"))throw new IOException("Mail did not close");}
    else if(args[1].equals("wanted-reward-clear")){System.out.println(c.input.action(new JSONObject().put("action","ui-bounds").put("path",WantedFeature.REWARD).put("wantedClear",true)));}
    else if(args[1].equals("wanted-reward-dismiss")){System.out.println(c.input.action(new JSONObject().put("action","ui-tap").put("path",WantedFeature.REWARD).put("wantedRoute","reward")));}
    else if(args[1].equals("wanted-viewport-check")){JSONObject snapshot=WantedReader.read(c.cache);int viewport=snapshot.getInt("viewportId");String root=WantedPolicy.PANEL+"/cellList/";System.out.println(c.input.action(new JSONObject().put("action","ui-bounds").put("path",root+"#1/go_bg").put("wantedClip",true).put("wantedViewportId",viewport)));for(String index:new String[]{"#1","#9"})try{c.input.action(new JSONObject().put("action","ui-bounds").put("path",root+index+"/go_bg").put("wantedClip",true).put("wantedViewportId",index.equals("#1")?viewport-1:viewport));throw new IOException("Invalid/clipped viewport unexpectedly accepted");}catch(IOException expected){if(expected.getMessage().contains("unexpectedly accepted"))throw expected;System.out.println("Wanted viewport negative "+index+": "+expected.getMessage());}}
    else if(args[1].equals("wanted-claim-reject")){JSONObject snapshot=WantedReader.read(c.cache),chosen=snapshot.getJSONArray("rows").getJSONObject(0);if(chosen.getString("uuid").equals("1")||!chosen.getString("decision").equals("READY_INSPECTION_ONLY"))throw new IOException("Expected completed non-1 UUID fixture");try{c.input.action(new JSONObject().put("action","ui-tap").put("path",WantedPolicy.PANEL+"/cellList/#1/receive_btn").put("wantedIndex","#1").put("wantedUuid","1").put("wantedViewportId",snapshot.getInt("viewportId")).put("wantedStart",chosen.getLong("startTime")).put("wantedEnd",chosen.getLong("completionTime")).put("wantedConfig",chosen.getLong("configId")));throw new IOException("Wrong Wanted UUID unexpectedly accepted");}catch(DeviceInput.PreDispatchRejected e){System.out.println(new JSONObject().put("event","wanted-negative-test").put("ok",true).put("receipt",e.receipt));}}
    else if(args[1].equals("wanted-entry-tree"))System.out.println(c.input.action(new JSONObject().put("action","ui-bounds").put("path",args[2]).put("describe",true).put("describeMatch","bounty|wanted|mission")));
    else if(args[1].equals("ui-bounds"))System.out.println(c.input.action(new JSONObject().put("action","ui-bounds").put("path",args[2]).put("child",args.length>3?args[3]:"").put("parent",args.length>4?Integer.parseInt(args[4]):0).put("describe",true)));
    else if(args[1].equals("ui-search")){c.worldReady();if(c.height()>180)c.input.mapZoom(-.24);c.input.tapControl("UIManagerInstance/windows/MainUI_SU/View/bottomLayer/search_btn");c.waitWindow("UISearchMonster",5000);System.out.println("Coordinate search opened from live exported button bounds");}
    else if(args[1].equals("ui-coordinates")){if(!c.open("UISearchMonster"))throw new IOException("Open coordinate search first");c.input.numericControl("server",17);c.input.numericControl("x",500);c.input.numericControl("y",500);System.out.println("Live-bounds State/X/Y editor test passed; no search or share sent");}
    else if(args[1].equals("world"))ControlProbe.navigate(c.input,2);
    else if(args[1].equals("roundtrip")){int original=StateProbe.snapshot(c.cache).getInt("sceneId");ControlProbe.navigate(c.input,original==1?2:1);ControlProbe.navigate(c.input,original);}
    else if(args[1].equals("trucks"))c.truckRun(1);
    else if(args[1].equals("trucks-open")){c.ensureTrucks();System.out.println("Trucks opened from exported control");}
    else if(args[1].equals("trucks-roundtrip")){c.ensureTrucks();c.input.tapControl("UIManagerInstance/windows/UILWTrainScene/View/closeBtn");c.ensureTrucks();System.out.println("Trucks close/reopen readiness verified; no message or attack");}
    else if(args[1].equals("truck-pick")){c.ensureTrucks();JSONArray trucks=c.truckSnapshot().getJSONArray("candidates");boolean picked=false;for(int i=0;i<trucks.length();i++){JSONObject t=trucks.getJSONObject(i);if(!c.rendered().contains(t.getString("id")))continue;if(!c.openTruck(t))throw new IOException("Rendered truck UUID selection failed");System.out.println("Truck selected through its live UUID-bound touch cell: "+t.getString("id")+"; no share or attack");picked=true;break;}if(!picked)throw new IOException("No rendered purple/yellow truck fixture available");}
    else if(args[1].equals("group-preview")||args[1].equals("group-scroll-preview")){
     if(!c.open("UIPositionShare"))c.truckShare();GroupTruckSender sender=new GroupTruckSender(c);sender.reveal();
     if(args[1].equals("group-scroll-preview")){for(int i=0;i<2;i++)c.input.scrollControl(GroupTruckSender.SCROLL,"up");sender.reveal();}
     System.out.println("Trucks group room, rendered label and visible share button verified; no message sent");
    }
    else if(args[1].equals("ui-click")){c.input.tapChild(args[2],args.length>3?args[3]:"");}
    else if(args[1].equals("chat-private")){c.input.tapLabel("UIManagerInstance/windows/UIChatNew/View/title","Private Chat",2);System.out.println("Private tab clicked by live label");}
    else if(args[1].equals("dm-preview")){c.truckMode="truck-dm";c.sendLimit=1;c.truckRun(3);}
    else if(args[1].equals("attack-reject")){c.truckMode="truck-attack";c.truckRun(0);}
    else if(args[1].equals("bounty")){int state=args.length>2?Integer.parseInt(args[2]):64;c.dryScanSteps=1;c.bountyRun(state,state,false,1);}
    else if(args[1].equals("bounty-data"))System.out.println(c.bounties.snapshot().toString(2));
    else if(args[1].equals("bounty-view")){try(GameMemory m=new GameMemory(c.cache)){for(TruckDiscoveryProbe.Value v:GameMemory.rows(m.path("DataCenter/WorldPointManager/allViewPoints")))if((v.tag&15)==5&&GameMemory.number(v.raw,"pointType")==22){System.out.println(TruckDiscoveryProbe.describe(v.raw,0).toString(2));break;}}}
    else if(args[1].equals("bounty-pick")){JSONObject s=c.bounties.snapshot();JSONArray list=s.getJSONArray("bounties");if(list.length()==0)throw new IOException("No bounty fixture loaded");JSONObject target=list.getJSONObject(0);if(!c.go(target.getInt("server"),target.getInt("x"),target.getInt("y")))throw new IOException("Fixture state unavailable");JSONObject projected=c.input.action(new JSONObject().put("action","map-point").put("tileX",target.getInt("x")).put("tileY",target.getInt("y")));System.out.println(projected);c.input.mapTap(target.getInt("x"),target.getInt("y"));if(c.selectedBounty(target.getString("uuid"))==null)throw new IOException("Projected bounty selection mismatch");System.out.println("Bounty selected by camera projection; no share or plunder pressed");c.dismissPoint();System.out.println("Bounty popup dismissed using its live bounds");}
    else if(args[1].equals("bounty-menu")){String id;try(GameMemory m=new GameMemory(c.cache)){if(!m.open("UIWorldPoint"))throw new IOException("Select a bounty first");id=Long.toString(GameMemory.number(m.path("UIManagerInstance/windows/UIWorldPoint/Ctrl"),"uuid"));}if(c.bounties.find(id)==null)throw new IOException("Selected point is not a loaded bounty");c.input.tapControl("UIManagerInstance/windows/UIWorldPoint/View/btn_share");c.waitWindow("UIPositionShare",5000);System.out.println("Bounty Share menu opened from live bounds; no channel or plunder clicked");}
    else if(args[1].equals("bounty-confirm")){int row=c.worldShareRow();c.input.tapWorldChannel(row);c.waitWindow("UIPositionShareConfirm",5000);JSONObject draft=c.input.action(new JSONObject().put("action","ui-bounds").put("path","UIManagerInstance/windows/UIPositionShareConfirm/View/input_field").put("readText",true));if(!draft.getString("inputText").isEmpty())throw new IOException("Share draft not empty");System.out.println("World confirmation reached via live label/room/bounds; note verified empty; no Share confirmation pressed");}
    else if(args[1].equals("bounty-dismiss")){c.dismissPoint();System.out.println("Point popup closed using a drag derived from live bounds; no terrain tap sent");}
    else throw new IOException("Unknown phone check");
    c.input.screenshot("after.png");System.out.println(new JSONObject().put("ok",true).put("dryRun",true).put("scanned",c.scanned).put("planned",c.planned).put("shared",c.sent).put("attacked",c.attacked));
   }
  }
 }catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
